import{_ as s}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as p,af as t}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const P=JSON.parse('{"title":"MCP Apps 实践指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/mcp/mcp-apps-practice.md","filePath":"zh/tech/mcp/mcp-apps-practice.md","lastUpdated":1780925500000}'),l={name:"zh/tech/mcp/mcp-apps-practice.md"};function n(i,a,o,r,c,h){return p(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="mcp-apps-实践指南" tabindex="-1">MCP Apps 实践指南 <a class="header-anchor" href="#mcp-apps-实践指南" aria-label="Permalink to &quot;MCP Apps 实践指南&quot;">​</a></h1><blockquote><p>学习来源：<a href="https://blog.modelcontextprotocol.io/posts/2026-01-26-mcp-apps/" target="_blank" rel="noreferrer">https://blog.modelcontextprotocol.io/posts/2026-01-26-mcp-apps/</a></p></blockquote><h2 id="什么是-mcp-apps" tabindex="-1">什么是 MCP Apps <a class="header-anchor" href="#什么是-mcp-apps" aria-label="Permalink to &quot;什么是 MCP Apps&quot;">​</a></h2><p>MCP Apps 是构建在 MCP（Model Context Protocol）之上的交互式应用，它们运行在 AI 客户端内部，可以访问 MCP 服务器提供的丰富工具和数据。</p><p>MCP Apps 本质上是<strong>借助 MCP 协议能力、在 AI 对话环境中运行的交互式应用</strong>。</p><h2 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h2><h3 id="_1-内置于-ai-对话" tabindex="-1">1. 内置于 AI 对话 <a class="header-anchor" href="#_1-内置于-ai-对话" aria-label="Permalink to &quot;1. 内置于 AI 对话&quot;">​</a></h3><p>MCP Apps 不需要单独的窗口或界面，它们直接在 AI 对话中运行，用户通过自然语言与 App 交互。</p><h3 id="_2-访问-mcp-生态系统" tabindex="-1">2. 访问 MCP 生态系统 <a class="header-anchor" href="#_2-访问-mcp-生态系统" aria-label="Permalink to &quot;2. 访问 MCP 生态系统&quot;">​</a></h3><p>MCP Apps 可以利用任何已配置的 MCP 服务器，访问：</p><ul><li>文件系统和本地工具</li><li>云服务（Google Drive、GitHub、Slack 等）</li><li>数据库和 API</li><li>企业内部工具</li></ul><h3 id="_3-可视化交互" tabindex="-1">3. 可视化交互 <a class="header-anchor" href="#_3-可视化交互" aria-label="Permalink to &quot;3. 可视化交互&quot;">​</a></h3><p>除了文本回复，MCP Apps 可以生成：</p><ul><li>表单和输入界面</li><li>数据表格和可视化</li><li>文件预览和编辑</li></ul><h3 id="_4-有状态会话" tabindex="-1">4. 有状态会话 <a class="header-anchor" href="#_4-有状态会话" aria-label="Permalink to &quot;4. 有状态会话&quot;">​</a></h3><p>MCP Apps 维护状态，允许：</p><ul><li>多步骤工作流</li><li>跨请求的上下文保持</li><li>复杂任务的分解执行</li></ul><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><h3 id="_1-文档处理工作流" tabindex="-1">1. 文档处理工作流 <a class="header-anchor" href="#_1-文档处理工作流" aria-label="Permalink to &quot;1. 文档处理工作流&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户：帮我分析这份销售报告</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>MCP App：加载文件 → 解析数据 → 生成摘要表格 → 提供可视化建议</span></span></code></pre></div><h3 id="_2-数据库查询" tabindex="-1">2. 数据库查询 <a class="header-anchor" href="#_2-数据库查询" aria-label="Permalink to &quot;2. 数据库查询&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户：查看 Q3 销售额前 10 的产品</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>MCP App：通过 MCP 连接数据库 → 执行查询 → 以表格形式展示结果</span></span></code></pre></div><h3 id="_3-代码审查" tabindex="-1">3. 代码审查 <a class="header-anchor" href="#_3-代码审查" aria-label="Permalink to &quot;3. 代码审查&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户：审查这个 PR 的安全性</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>MCP App：通过 GitHub MCP → 获取代码变更 → 分析安全问题 → 给出建议</span></span></code></pre></div><h2 id="mcp-apps-vs-传统-mcp-工具" tabindex="-1">MCP Apps vs 传统 MCP 工具 <a class="header-anchor" href="#mcp-apps-vs-传统-mcp-工具" aria-label="Permalink to &quot;MCP Apps vs 传统 MCP 工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>传统 MCP 工具</th><th>MCP Apps</th></tr></thead><tbody><tr><td>交互方式</td><td>单次调用返回结果</td><td>多轮交互式对话</td></tr><tr><td>状态管理</td><td>无状态</td><td>有状态会话</td></tr><tr><td>用户界面</td><td>纯文本</td><td>丰富可视化</td></tr><tr><td>适用场景</td><td>简单查询/操作</td><td>复杂工作流</td></tr></tbody></table><h2 id="技术架构" tabindex="-1">技术架构 <a class="header-anchor" href="#技术架构" aria-label="Permalink to &quot;技术架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────┐</span></span>
<span class="line"><span>│         AI Client (Claude)           │</span></span>
<span class="line"><span>│  ┌────────────────────────────────┐  │</span></span>
<span class="line"><span>│  │       MCP App Runtime           │  │</span></span>
<span class="line"><span>│  │  ┌──────────┐  ┌─────────────┐ │  │</span></span>
<span class="line"><span>│  │  │ UI Render │  │ State Mgmt  │ │  │</span></span>
<span class="line"><span>│  │  └──────────┘  └─────────────┘ │  │</span></span>
<span class="line"><span>│  └────────────────────────────────┘  │</span></span>
<span class="line"><span>│         ↕ MCP Protocol              │</span></span>
<span class="line"><span>│  ┌────────────────────────────────┐  │</span></span>
<span class="line"><span>│  │       MCP Servers              │  │</span></span>
<span class="line"><span>│  │  Filesystem │ GitHub │ DB...  │  │</span></span>
<span class="line"><span>│  └────────────────────────────────┘  │</span></span>
<span class="line"><span>└──────────────────────────────────────┘</span></span></code></pre></div><h2 id="开发-mcp-apps-的关键点" tabindex="-1">开发 MCP Apps 的关键点 <a class="header-anchor" href="#开发-mcp-apps-的关键点" aria-label="Permalink to &quot;开发 MCP Apps 的关键点&quot;">​</a></h2><h3 id="_1-清晰的工具定义" tabindex="-1">1. 清晰的工具定义 <a class="header-anchor" href="#_1-清晰的工具定义" aria-label="Permalink to &quot;1. 清晰的工具定义&quot;">​</a></h3><p>每个 MCP App 应暴露定义良好的工具集：</p><ul><li>明确的工具名称和描述</li><li>完整的 inputSchema</li><li>有意义的错误处理</li></ul><h3 id="_2-渐进式交互" tabindex="-1">2. 渐进式交互 <a class="header-anchor" href="#_2-渐进式交互" aria-label="Permalink to &quot;2. 渐进式交互&quot;">​</a></h3><ul><li>首先确认用户意图</li><li>提供选项让用户选择</li><li>在执行前获取必要参数</li><li>展示结果并提供后续操作建议</li></ul><h3 id="_3-状态持久化" tabindex="-1">3. 状态持久化 <a class="header-anchor" href="#_3-状态持久化" aria-label="Permalink to &quot;3. 状态持久化&quot;">​</a></h3><ul><li>使用 MCP 的资源机制存储应用状态</li><li>支持会话恢复</li><li>管理复杂的上下文</li></ul><h2 id="生态现状" tabindex="-1">生态现状 <a class="header-anchor" href="#生态现状" aria-label="Permalink to &quot;生态现状&quot;">​</a></h2><p>MCP 生态系统正在快速发展：</p><ul><li>官方提供多种语言的 SDK（Python、TypeScript、Java、Kotlin、C#）</li><li>社区贡献了大量预构建的 MCP 服务器</li><li>主流 IDE（VS Code、Cursor）已支持 MCP</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>访问 <a href="https://modelcontextprotocol.io/extensions/apps/overview" target="_blank" rel="noreferrer">MCP Apps 官方文档</a> 了解更多</li><li>探索 <a href="https://github.com/modelcontextprotocol/servers" target="_blank" rel="noreferrer">MCP Servers 仓库</a> 发现可用工具</li><li>尝试构建自己的第一个 MCP 服务器</li></ul>`,41)])])}const C=s(l,[["render",n]]);export{P as __pageData,C as default};
